export interface ParsedNumericValue {
  prefix: string
  suffix: string
  target: number
  decimals: number
  useGrouping: boolean
}

export const parseNumericValue = (value: string): ParsedNumericValue | null => {
  const match = value.match(/[\d,.]+/)
  if (!match) {
    return null
  }

  const rawNumber = match[0]
  const target = Number(rawNumber.replace(/,/g, ''))
  if (Number.isNaN(target)) {
    return null
  }

  const decimalPart = rawNumber.split('.')[1]
  const decimals = decimalPart ? decimalPart.length : 0

  return {
    prefix: value.slice(0, match.index),
    suffix: value.slice((match.index ?? 0) + rawNumber.length),
    target,
    decimals,
    useGrouping: rawNumber.includes(','),
  }
}

export const formatNumber = (
  value: number,
  decimals: number,
  useGrouping: boolean,
) => {
  if (useGrouping) {
    return value.toLocaleString('en-US', {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    })
  }

  if (decimals > 0) {
    return value.toFixed(decimals)
  }

  return String(Math.round(value))
}

export const getAnimatedStartValue = (target: number) => {
  if (target <= 1) return 0
  if (target <= 10) return Math.max(1, target * 0.5)
  return Math.max(1, target * 0.65)
}

